{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2157-02-16 23:13:00",
      "speaker": "Doctor",
      "text": "Hi, I’m Dr. Lee. I know you’re in pain, but I need to ask a few questions so we can help you. You’re here because of worsening abdominal pain, right?"
    },
    {
      "turn_number": 2,
      "time": "2157-02-16 23:15:00",
      "speaker": "Patient",
      "text": "Yes… it started yesterday. It’s the same as before—epigastric pain, nausea. I just started erythromycin again, and that always triggers it."
    },
    {
      "turn_number": 3,
      "time": "2157-02-16 23:17:00",
      "speaker": "Doctor",
      "text": "Okay, thank you. Your husband mentioned you vomited once. Was it green or bloody?"
    },
    {
      "turn_number": 4,
      "time": "2157-02-16 23:18:00",
      "speaker": "Patient",
      "text": "I don’t know. I didn’t see it. I was too sick."
    },
    {
      "turn_number": 5,
      "time": "2157-02-16 23:20:00",
      "speaker": "Doctor",
      "text": "That’s okay. No diarrhea or constipation? Bowels moving normally?"
    },
    {
      "turn_number": 6,
      "time": "2157-02-16 23:21:00",
      "speaker": "Patient",
      "text": "Yes, same as usual."
    },
    {
      "turn_number": 7,
      "time": "2157-02-16 23:23:00",
      "speaker": "Doctor",
      "text": "We’ll follow your usual protocol. You’ll be NPO for now—no food or drink—so your stomach can rest. We’ll give IV fluids and manage your pain."
    },
    {
      "turn_number": 8,
      "time": "2157-02-16 23:25:00",
      "speaker": "Patient",
      "text": "Okay… but I hate being NPO. It makes me anxious."
    },
    {
      "turn_number": 9,
      "time": "2157-02-16 23:27:00",
      "speaker": "Doctor",
      "text": "I understand. We’ll keep your anxiety in mind. You’re on clonazepam—would you like a dose now?"
    },
    {
      "turn_number": 10,
      "time": "2157-02-16 23:28:00",
      "speaker": "Patient",
      "text": "Yes, please. And something for pain. It’s still sharp."
    },
    {
      "turn_number": 11,
      "time": "2157-02-16 23:30:00",
      "speaker": "Doctor",
      "text": "I’ll order hydromorphone. We’ll start low and adjust. Rest now—we’ll check on you often."
    },
    {
      "turn_number": 12,
      "time": "2157-02-17 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. How are you feeling? Pain level?"
    },
    {
      "turn_number": 13,
      "time": "2157-02-17 08:02:00",
      "speaker": "Patient",
      "text": "Still 7 out of 10. Nauseous too."
    },
    {
      "turn_number": 14,
      "time": "2157-02-17 08:04:00",
      "speaker": "Doctor",
      "text": "We’ll give prochlorperazine for nausea. We’re going to try clear liquids soon, but only if you’re ready."
    },
    {
      "turn_number": 15,
      "time": "2157-02-17 08:06:00",
      "speaker": "Patient",
      "text": "I can try. But last time I couldn’t keep anything down."
    },
    {
      "turn_number": 16,
      "time": "2157-02-17 08:08:00",
      "speaker": "Doctor",
      "text": "We’ll go slow. Just a few sips. If you vomit, we’ll go back to NPO. No pressure."
    },
    {
      "turn_number": 17,
      "time": "2157-02-17 12:00:00",
      "speaker": "Doctor",
      "text": "You tried clear liquids earlier, but you vomited. So we’re keeping you NPO for now. That’s okay—it happens."
    },
    {
      "turn_number": 18,
      "time": "2157-02-17 12:02:00",
      "speaker": "Patient",
      "text": "I’m sorry. I wanted to do better."
    },
    {
      "turn_number": 19,
      "time": "2157-02-17 12:04:00",
      "speaker": "Doctor",
      "text": "This isn’t about blame. Your condition is complex. We’re here to support you, not judge."
    },
    {
      "turn_number": 20,
      "time": "2157-02-17 12:06:00",
      "speaker": "Patient",
      "text": "Thank you. My hand feels warm and swollen where the IV is."
    },
    {
      "turn_number": 21,
      "time": "2157-02-17 12:08:00",
      "speaker": "Doctor",
      "text": "Let me check. There’s redness and swelling—this could be cellulitis. We’ll start IV antibiotics just in case."
    },
    {
      "turn_number": 22,
      "time": "2157-02-17 12:10:00",
      "speaker": "Patient",
      "text": "Is that serious?"
    },
    {
      "turn_number": 23,
      "time": "2157-02-17 12:12:00",
      "speaker": "Doctor",
      "text": "It’s treatable. We’ll give ceftriaxone IV, then switch to oral Keflex later. It should clear up in a few days."
    },
    {
      "turn_number": 24,
      "time": "2157-02-18 08:30:00",
      "speaker": "Doctor",
      "text": "Good news—your hand is already less swollen. We’ll switch you to oral Keflex tomorrow."
    },
    {
      "turn_number": 25,
      "time": "2157-02-18 08:32:00",
      "speaker": "Patient",
      "text": "That’s great. My stomach feels a little better too."
    },
    {
      "turn_number": 26,
      "time": "2157-02-18 08:34:00",
      "speaker": "Doctor",
      "text": "We’ll try clear liquids again today. Small amounts—apple juice, broth. Let’s see how you do."
    },
    {
      "turn_number": 27,
      "time": "2157-02-18 13:00:00",
      "speaker": "Doctor",
      "text": "You kept the clear liquids down! That’s a big step. Tomorrow, we’ll advance to a BRAT diet—bananas, rice, applesauce, toast."
    },
    {
      "turn_number": 28,
      "time": "2157-02-18 13:02:00",
      "speaker": "Patient",
      "text": "I’m so glad. I’m tired of IV fluids."
    },
    {
      "turn_number": 29,
      "time": "2157-02-18 13:04:00",
      "speaker": "Doctor",
      "text": "We are too. Your labs are stable—no signs of infection or pancreatitis. This is a motility flare, like before."
    },
    {
      "turn_number": 30,
      "time": "2157-02-19 09:00:00",
      "speaker": "Doctor",
      "text": "How’s the BRAT diet? Any nausea?"
    },
    {
      "turn_number": 31,
      "time": "2157-02-19 09:02:00",
      "speaker": "Patient",
      "text": "I had toast and applesauce. No vomiting. A little full, but okay."
    },
    {
      "turn_number": 32,
      "time": "2157-02-19 09:04:00",
      "speaker": "Doctor",
      "text": "Great. We’ll keep you on this for now. Pain level?"
    },
    {
      "turn_number": 33,
      "time": "2157-02-19 09:05:00",
      "speaker": "Patient",
      "text": "Down to 4. Still there, but better."
    },
    {
      "turn_number": 34,
      "time": "2157-02-19 09:07:00",
      "speaker": "Doctor",
      "text": "We’ll keep using hydromorphone as needed, but try to reduce it slowly."
    },
    {
      "turn_number": 35,
      "time": "2157-02-20 08:45:00",
      "speaker": "Doctor",
      "text": "You’re doing well. Still no pain with the BRAT diet?"
    },
    {
      "turn_number": 36,
      "time": "2157-02-20 08:47:00",
      "speaker": "Patient",
      "text": "No, I feel much better. Can I go home soon?"
    },
    {
      "turn_number": 37,
      "time": "2157-02-20 08:49:00",
      "speaker": "Doctor",
      "text": "We want to watch you for a bit longer. Make sure you’re stable. But yes, discharge is likely in the next few days."
    },
    {
      "turn_number": 38,
      "time": "2157-02-20 08:51:00",
      "speaker": "Patient",
      "text": "I’m worried about the pain coming back."
    },
    {
      "turn_number": 39,
      "time": "2157-02-20 08:53:00",
      "speaker": "Doctor",
      "text": "We’ll send you home with your usual meds—erythromycin, metoclopramide, pain and nausea relief. And we’ll schedule follow-up with your GI doctor."
    },
    {
      "turn_number": 40,
      "time": "2157-02-21 09:00:00",
      "speaker": "Doctor",
      "text": "Your hand is completely better. No redness or swelling. You’ve finished the IV antibiotics and are on oral Keflex."
    },
    {
      "turn_number": 41,
      "time": "2157-02-21 09:02:00",
      "speaker": "Patient",
      "text": "Good. I was worried about infection."
    },
    {
      "turn_number": 42,
      "time": "2157-02-21 09:04:00",
      "speaker": "Doctor",
      "text": "You’re through the worst of it. Keep taking the Keflex for five days, even if it feels fine."
    },
    {
      "turn_number": 43,
      "time": "2157-02-22 10:00:00",
      "speaker": "Doctor",
      "text": "You’ve been off pain meds for 12 hours and no rebound pain. That’s excellent."
    },
    {
      "turn_number": 44,
      "time": "2157-02-22 10:02:00",
      "speaker": "Patient",
      "text": "I still have some discomfort, but I can manage."
    },
    {
      "turn_number": 45,
      "time": "2157-02-22 10:04:00",
      "speaker": "Doctor",
      "text": "We’ll keep acetaminophen available. You’re tolerating food well. Discharge is looking likely tomorrow."
    },
    {
      "turn_number": 46,
      "time": "2157-02-22 10:06:00",
      "speaker": "Patient",
      "text": "What do I do if the pain comes back at home?"
    },
    {
      "turn_number": 47,
      "time": "2157-02-22 10:08:00",
      "speaker": "Doctor",
      "text": "Use your hydrocodone as prescribed. If it’s not controlled, or you vomit repeatedly, come back. But we think you’ll do fine."
    },
    {
      "turn_number": 48,
      "time": "2157-02-23 08:30:00",
      "speaker": "Doctor",
      "text": "All set for discharge tomorrow. We’ll review your meds and instructions."
    },
    {
      "turn_number": 49,
      "time": "2157-02-23 08:32:00",
      "speaker": "Patient",
      "text": "I’m nervous. What if I mess up the diet again?"
    },
    {
      "turn_number": 50,
      "time": "2157-02-23 08:34:00",
      "speaker": "Doctor",
      "text": "Start with small, bland meals. BRAT is a good template. Avoid heavy or greasy foods. And don’t rush back on erythromycin—pace it."
    },
    {
      "turn_number": 51,
      "time": "2157-02-23 08:36:00",
      "speaker": "Patient",
      "text": "I’ll try. I just want to feel normal."
    },
    {
      "turn_number": 52,
      "time": "2157-02-23 08:38:00",
      "speaker": "Doctor",
      "text": "We know this is hard. But you’re making progress. Your mental health matters too—keep in touch with your therapist."
    },
    {
      "turn_number": 53,
      "time": "2157-02-24 09:00:00",
      "speaker": "Doctor",
      "text": "You’re cleared to go home. We’ll go over the discharge instructions now."
    },
    {
      "turn_number": 54,
      "time": "2157-02-24 09:02:00",
      "speaker": "Patient",
      "text": "Okay. What should I remember?"
    },
    {
      "turn_number": 55,
      "time": "2157-02-24 09:04:00",
      "speaker": "Doctor",
      "text": "First, continue all your medications as listed. Especially erythromycin and metoclopramide for stomach motility."
    },
    {
      "turn_number": 56,
      "time": "2157-02-24 09:06:00",
      "speaker": "Patient",
      "text": "And the Keflex?"
    },
    {
      "turn_number": 57,
      "time": "2157-02-24 09:08:00",
      "speaker": "Doctor",
      "text": "Yes, finish the full five-day course for the cellulitis, even if your hand feels fine."
    },
    {
      "turn_number": 58,
      "time": "2157-02-24 09:10:00",
      "speaker": "Doctor",
      "text": "Second, eat small, frequent meals. Stick to bland foods for a few more days."
    },
    {
      "turn_number": 59,
      "time": "2157-02-24 09:12:00",
      "speaker": "Patient",
      "text": "No spicy or fatty stuff?"
    },
    {
      "turn_number": 60,
      "time": "2157-02-24 09:14:00",
      "speaker": "Doctor",
      "text": "Exactly. And if pain or nausea returns, use your PRN meds. If it doesn’t improve, call your doctor or come back."
    },
    {
      "turn_number": 61,
      "time": "2157-02-24 09:16:00",
      "speaker": "Patient",
      "text": "I have follow-up with GI?"
    },
    {
      "turn_number": 62,
      "time": "2157-02-24 09:18:00",
      "speaker": "Doctor",
      "text": "Yes, in one week. And your PCP in two weeks. We’ll send them all your records."
    },
    {
      "turn_number": 63,
      "time": "2157-02-24 09:20:00",
      "speaker": "Patient",
      "text": "Thank you. I feel better than I have in days."
    },
    {
      "turn_number": 64,
      "time": "2157-02-24 09:22:00",
      "speaker": "Doctor",
      "text": "You did great. Take care of yourself. We’re here if you need us."
    },
    {
      "turn_number": 65,
      "time": "2157-02-24 09:24:00",
      "speaker": "Patient",
      "text": "I will. Thanks for not giving up on me."
    },
    {
      "turn_number": 66,
      "time": "2157-02-24 09:26:00",
      "speaker": "Doctor",
      "text": "Never. Take it one day at a time."
    },
    {
      "turn_number": 67,
      "time": "2157-02-24 10:00:00",
      "speaker": "Doctor",
      "text": "Nurse will bring your discharge papers and prescriptions."
    },
    {
      "turn_number": 68,
      "time": "2157-02-24 10:02:00",
      "speaker": "Patient",
      "text": "Okay. I’m ready to go home."
    },
    {
      "turn_number": 69,
      "time": "2157-02-24 10:04:00",
      "speaker": "Doctor",
      "text": "You’re doing well. Keep up the progress."
    },
    {
      "turn_number": 70,
      "time": "2157-02-24 10:06:00",
      "speaker": "Patient",
      "text": "I will. Thank you again."
    },
    {
      "turn_number": 71,
      "time": "2157-02-24 10:08:00",
      "speaker": "Doctor",
      "text": "Take care. We’ll see you in follow-up."
    },
    {
      "turn_number": 72,
      "time": "2157-02-24 10:10:00",
      "speaker": "Patient",
      "text": "I’ll be there."
    },
    {
      "turn_number": 73,
      "time": "2157-02-24 10:12:00",
      "speaker": "Doctor",
      "text": "Have a safe trip home."
    },
    {
      "turn_number": 74,
      "time": "2157-02-24 10:14:00",
      "speaker": "Patient",
      "text": "I will. Bye."
    },
    {
      "turn_number": 75,
      "time": "2157-02-24 10:16:00",
      "speaker": "Doctor",
      "text": "Goodbye."
    },
    {
      "turn_number": 76,
      "time": "2157-02-24 10:18:00",
      "speaker": "Patient",
      "text": "Bye."
    },
    {
      "turn_number": 77,
      "time": "2157-02-24 10:20:00",
      "speaker": "Doctor",
      "text": "Take it easy."
    },
    {
      "turn_number": 78,
      "time": "2157-02-24 10:22:00",
      "speaker": "Patient",
      "text": "I will."
    },
    {
      "turn_number": 79,
      "time": "2157-02-24 10:24:00",
      "speaker": "Doctor",
      "text": "We’re here if you need us."
    },
    {
      "turn_number": 80,
      "time": "2157-02-24 10:26:00",
      "speaker": "Patient",
      "text": "Thank you."
    },
    {
      "turn_number": 81,
      "time": "2157-02-24 10:28:00",
      "speaker": "Doctor",
      "text": "Rest well."
    },
    {
      "turn_number": 82,
      "time": "2157-02-24 10:30:00",
      "speaker": "Patient",
      "text": "I will."
    },
    {
      "turn_number": 83,
      "time": "2157-02-24 10:32:00",
      "speaker": "Doctor",
      "text": "See you soon."
    },
    {
      "turn_number": 84,
      "time": "2157-02-24 10:34:00",
      "speaker": "Patient",
      "text": "Bye."
    },
    {
      "turn_number": 85,
      "time": "2157-02-24 10:36:00",
      "speaker": "Doctor",
      "text": "Take care."
    }
  ],
  "summary": {
    "admission_start": "2157-02-16 23:13:00",
    "admission_end": "2157-02-24 20:30:00",
    "summary_paragraph": "A woman with a history of chronic abdominal pain, gastroparesis, functional dyspepsia, anxiety, depression, and PTSD was admitted for an acute flare of epigastric pain and nausea, consistent with prior episodes. She was managed with an established inpatient protocol involving initial NPO status, IV fluids, pain control, and gradual dietary advancement. She initially failed a trial of clear liquids but later tolerated a BRAT diet. During the admission, she developed cellulitis at an IV site on her left hand, which was treated with IV ceftriaxone followed by oral Keflex. Her pain and nausea improved, and she was discharged home in stable condition with instructions to continue her home medications, complete the antibiotic course, and follow up with her PCP and GI specialist.",
    "problems": [
      "Gastroparesis",
      "Major depressive disorder, single episode, unspecified",
      "Cellulitis of left upper limb",
      "Functional dyspepsia",
      "Epigastric pain",
      "Nausea",
      "Anxiety disorder, unspecified",
      "Unspecified hearing loss, unspecified ear"
    ]
  }
}
